pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(uint256 _value, bytes memory _data) internal {
        uint256 before;
        try c.depositsCount() returns (uint256 __r) { before = __r; } catch { return; }
        try c.sendMoney(address(this), 0, _data) {} catch { return; }
        assertTrue(c.depositsCount() == before);
    }

    function testFuzz_test(uint256 _value, bytes memory _data) public {
        _test(_value, _data);
    }

    receive() external payable {}

    fallback() external payable {}
}
